let resolvedYtDlpPath = null;

function downloadFileFollowRedirects(url, destPath, extraHeaders = {}) {
  return new Promise((resolve, reject) => {
    const request = (currentUrl, redirectsLeft) => {
      if (redirectsLeft <= 0) return reject(new Error('Too many redirects'));
      let parsed;
      try {
        parsed = new URL(currentUrl);
      } catch (err) {
        return reject(new Error('Invalid URL: ' + currentUrl));
      }
      const client = parsed.protocol === 'http:' ? http : https;
      const req = client.get(
        currentUrl,
        {
          headers: {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0.0.0 Safari/537.36',
            'Accept': '*/*',
            ...extraHeaders
          },
          timeout: 45000
        },
        (res) => {
          if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
            res.resume();
            const nextUrl = new URL(res.headers.location, currentUrl).toString();
            return request(nextUrl, redirectsLeft - 1);
          }
          if (res.statusCode !== 200 && res.statusCode !== 206) {
            res.resume();
            return reject(new Error('HTTP ' + res.statusCode));
          }
          const ctype = String(res.headers['content-type'] || '').toLowerCase();
          if (ctype.includes('text/html') || ctype.includes('application/json')) {
            res.resume();
            return reject(new Error('Received non-media response (' + ctype + ')'));
          }
          const file = fs.createWriteStream(destPath);
          res.pipe(file);
          file.on('finish', () => {
            file.close(() => {
              try {
                fs.chmodSync(destPath, 0o755);
                resolve(destPath);
              } catch (err) {
                reject(err);
              }
            });
          });
          file.on('error', (err) => {
            try { fs.unlinkSync(destPath); } catch (e) {}
            reject(err);
          });
        }
      );
      req.on('error', reject);
      req.on('timeout', () => {
        req.destroy();
        reject(new Error('Download timeout'));
      });
    };
    request(url, 8);
  });
}

async function ensureYtDlp() {
  if (resolvedYtDlpPath && fs.existsSync(resolvedYtDlpPath)) {
    return resolvedYtDlpPath;
  }
  try {
    const sysPath = execSync('which yt-dlp', { stdio: ['ignore', 'pipe', 'ignore'] }).toString().trim();
    if (sysPath && fs.existsSync(sysPath)) {
      resolvedYtDlpPath = sysPath;
      return resolvedYtDlpPath;
    }
  } catch (e) {}

  const tmpBinary = path.join(os.tmpdir(), 'yt-dlp');
  if (fs.existsSync(tmpBinary) && fs.statSync(tmpBinary).size > 1000000) {
    try { fs.chmodSync(tmpBinary, 0o755); } catch (e) {}
    resolvedYtDlpPath = tmpBinary;
    return resolvedYtDlpPath;
  }

  const binUrl = 'https://github.com/yt-dlp/yt-dlp/releases/latest/download/yt-dlp_linux';
  await downloadFileFollowRedirects(binUrl, tmpBinary);
  resolvedYtDlpPath = tmpBinary;
  return resolvedYtDlpPath;
}

