function runYtDlpAttempt(ytdlpBin, args) {
  return new Promise((resolve) => {
    let stderrData = '';
    let stdoutData = '';
    let proc;
    try {
      proc = spawn(ytdlpBin, args);
    } catch (err) {
      return resolve({ code: -1, stderr: err.message, stdout: '' });
    }

    const timer = setTimeout(() => {
      try { proc.kill(); } catch (e) {}
    }, 65000);

    proc.stdout.on('data', (d) => { stdoutData += d.toString(); });
    proc.stderr.on('data', (d) => { stderrData += d.toString(); });

    proc.on('error', (err) => {
      clearTimeout(timer);
      resolve({ code: -1, stderr: stderrData + '\n' + err.message, stdout: stdoutData });
    });

    proc.on('close', (code) => {
      clearTimeout(timer);
      resolve({ code, stderr: stderrData, stdout: stdoutData });
    });
  });
}

function findOutputFile(jobDir) {
  if (!fs.existsSync(jobDir)) return null;
  const files = fs.readdirSync(jobDir);
  for (const f of files) {
    if (f.endsWith('.part') || f.endsWith('.ytdl') || f.endsWith('.temp')) continue;
    const full = path.join(jobDir, f);
    try {
      const st = fs.statSync(full);
      if (st.isFile() && st.size > 5000) {
        return { path: full, name: f, size: st.size };
      }
    } catch (e) {}
  }
  return null;
}

