function sanitizeFilename(name, ext) {
  const base = String(name || 'video')
    .replace(/[<>:"/\\|?*\x00-\x1F]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 90) || 'video';
  const cleanExt = String(ext || 'mp4').replace(/^\./, '');
  return `${base}.${cleanExt}`;
}

async function prepareVideoDownload(videoUrl, quality, clientCountry) {
  const ytdlpBin = await ensureYtDlp();
  const ffmpegPath = getFfmpegPath();

  const jobId = crypto.randomBytes(8).toString('hex');
  const jobDir = path.join(os.tmpdir(), `sv_job_${jobId}`);
  fs.mkdirSync(jobDir, { recursive: true });

  const isAudio = quality === 'audio';
  const outputTemplate = path.join(jobDir, 'media.%(ext)s');

  const baseFlags = [
    '--no-playlist',
    '--no-warnings',
    '--no-check-certificates',
    '--geo-bypass'
  ];

  if (ffmpegPath) {
    baseFlags.push('--ffmpeg-location', ffmpegPath);
  }

  let found = null;
  const isTikTok = videoUrl.includes('tiktok.com');
  const isYouTube = videoUrl.includes('youtube.com') || videoUrl.includes('youtu.be');

  // 1. TikTok: dedicated multi-provider API resolver + curl-cffi impersonation
  if (isTikTok) {
    found = await resolveTikTok(videoUrl, isAudio, jobDir, baseFlags, ytdlpBin);
    if (!found) {
      try { fs.rmSync(jobDir, { recursive: true, force: true }); } catch (e) {}
      throw new Error('[StreamVault v3.5] Could not resolve TikTok stream from this link. Please verify the TikTok video is public.');
    }
  }

  // 2. YouTube: dedicated multi-cloud converter + Invidious proxy + yt-dlp resolver
  if (!found && isYouTube) {
    found = await resolveYouTube(videoUrl, quality, isAudio, jobDir, baseFlags, ytdlpBin, clientCountry);
    if (!found) {
      try { fs.rmSync(jobDir, { recursive: true, force: true }); } catch (e) {}
      throw new Error('[StreamVault v3.5] This YouTube video is restricted on cloud servers. Try selecting 720p or 480p, or try another link.');
    }
  }

  // 3. General yt-dlp (Instagram, Facebook, X/Twitter, or direct links)
  if (!found && !isTikTok && !isYouTube) {
    const cookiesFlag = getCookiesFlag();
    const primaryFormat = isAudio
      ? 'bestaudio[ext=m4a]/bestaudio/best'
      : (ffmpegPath ? 'bestvideo[height<=1080][ext=mp4]+bestaudio[ext=m4a]/best[ext=mp4]/best' : 'best[ext=mp4]/best');

    const args = [
      ...baseFlags,
      ...cookiesFlag,
      '-f', primaryFormat,
      ...(isAudio ? [] : (ffmpegPath ? ['--merge-output-format', 'mp4'] : [])),
      '-o', outputTemplate,
      videoUrl
    ];

    const res = await runYtDlpAttempt(ytdlpBin, args);
    found = findOutputFile(jobDir);

    if (!found) {
      try { fs.rmSync(jobDir, { recursive: true, force: true }); } catch (e) {}
      const cleanErr = (res.stderr || 'Extraction failed').split('\n').filter(Boolean).slice(-2).join(' | ');
      throw new Error(cleanErr || 'Could not extract video stream.');
    }
  }

  const actualExt = path.extname(found.name).replace(/^\./, '') || (isAudio ? 'm4a' : 'mp4');
  const mimeType = isAudio || actualExt === 'm4a' || actualExt === 'mp3'
    ? 'audio/mp4'
    : actualExt === 'webm'
    ? 'video/webm'
    : 'video/mp4';

  const cleanup = () => {
    preparedJobs.delete(jobId);
    try { fs.rmSync(jobDir, { recursive: true, force: true }); } catch (e) {}
  };

  const timer = setTimeout(cleanup, 15 * 60 * 1000);

  const jobRecord = {
    jobId,
    jobDir,
    filePath: found.path,
    size: found.size,
    ext: actualExt,
    mimeType,
    cleanup: () => {
      clearTimeout(timer);
      cleanup();
    }
  };

  preparedJobs.set(jobId, jobRecord);
  return jobRecord;
}

// Direct proxy pipe for CDN URLs resolved in the client's browser (TikTok / YouTube mirrors)
app.get('/api/proxy-file', (req, res) => {
  const targetUrl = (req.query.url || '').trim();
  const rawFilename = (req.query.filename || 'video.mp4').trim();

  if (!targetUrl || (!targetUrl.startsWith('http://') && !targetUrl.startsWith('https://'))) {
    return res.status(400).send('Invalid target URL');
  }

  const safeAscii = String(rawFilename).replace(/[^\x20-\x7E]/g, '_').replace(/["\\]/g, '') || 'video.mp4';
  const isAudio = /\.(mp3|m4a)$/i.test(rawFilename);

  const streamRedirect = (currentUrl, redirectsLeft) => {
    if (redirectsLeft <= 0) {
      if (!res.headersSent) res.status(502).send('Too many redirects');
      return;
    }
    let parsed;
    try {
      parsed = new URL(currentUrl);
    } catch (e) {
      if (!res.headersSent) res.status(400).send('Invalid URL');
      return;
    }
    const client = parsed.protocol === 'http:' ? http : https;
    const upstreamReq = client.get(
      currentUrl,
      {
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0.0.0 Safari/537.36',
          'Accept': '*/*'
        },
        timeout: 45000
      },
      (upstreamRes) => {
        if (upstreamRes.statusCode >= 300 && upstreamRes.statusCode < 400 && upstreamRes.headers.location) {
          upstreamRes.resume();
          const nextUrl = new URL(upstreamRes.headers.location, currentUrl).toString();
          return streamRedirect(nextUrl, redirectsLeft - 1);
        }
        if (upstreamRes.statusCode !== 200 && upstreamRes.statusCode !== 206) {
          upstreamRes.resume();
          if (!res.headersSent) res.status(502).send('Upstream error HTTP ' + upstreamRes.statusCode);
          return;
        }

        res.setHeader('Content-Type', isAudio ? 'audio/mpeg' : 'video/mp4');
        if (upstreamRes.headers['content-length']) {
          res.setHeader('Content-Length', upstreamRes.headers['content-length']);
        }
        res.setHeader(
          'Content-Disposition',
          `attachment; filename="${safeAscii}"; filename*=UTF-8''${encodeURIComponent(rawFilename)}`
        );
        upstreamRes.pipe(res);
      }
    );
    upstreamReq.on('error', () => {
      if (!res.headersSent) res.status(502).send('Upstream connection failed');
    });
  };

  streamRedirect(targetUrl, 6);
});

app.get('/api/prepare', async (req, res) => {
  const videoUrl = (req.query.url || '').trim();
  const quality = (req.query.quality || '1080p').trim();
  const customTitle = (req.query.title || '').trim();
  const clientCountry = getClientCountry(req);

  if (!videoUrl) {
    return res.status(400).json({ ok: false, error: 'Please provide a valid video URL.' });
  }

  try {
    const job = await prepareVideoDownload(videoUrl, quality, clientCountry);
    const filename = sanitizeFilename(customTitle || 'streamvault-video', job.ext);
    return res.json({
      ok: true,
      downloadId: job.jobId,
      size: job.size,
      ext: job.ext,
      filename,
      downloadUrl: `/api/download/${job.jobId}?filename=${encodeURIComponent(filename)}`
    });
  } catch (err) {
    console.error('[StreamVault Prepare Error]:', err.message);
    return res.status(500).json({
      ok: false,
      error: err.message || 'Failed to process video.'
    });
  }
});

app.get('/api/download/:id', (req, res) => {
  const jobId = req.params.id;
  const job = preparedJobs.get(jobId);

  if (!job || !fs.existsSync(job.filePath)) {
    return res.status(404).send('Download link expired or not found. Please click Download again.');
  }

  const rawFilename = req.query.filename || `video.${job.ext}`;
  const safeAscii = String(rawFilename).replace(/[^\x20-\x7E]/g, '_').replace(/["\\]/g, '');

  res.setHeader('Content-Type', job.mimeType);
  res.setHeader('Content-Length', job.size);
  res.setHeader(
    'Content-Disposition',
    `attachment; filename="${safeAscii}"; filename*=UTF-8''${encodeURIComponent(rawFilename)}`
  );

  const stream = fs.createReadStream(job.filePath);
  stream.pipe(res);

  stream.on('close', () => {
    setTimeout(() => job.cleanup(), 120 * 1000);
  });
  stream.on('error', () => {
    job.cleanup();
  });
});

app.get('/api/stream', async (req, res) => {
  const videoUrl = (req.query.url || '').trim();
  const quality = (req.query.quality || '1080p').trim();
  const clientCountry = getClientCountry(req);

  if (!videoUrl) {
    return res.status(400).json({ ok: false, error: 'Missing url parameter' });
  }

  try {
    const job = await prepareVideoDownload(videoUrl, quality, clientCountry);
    const filename = `video_${job.jobId}.${job.ext}`;
    res.setHeader('Content-Type', job.mimeType);
    res.setHeader('Content-Length', job.size);
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);

    const stream = fs.createReadStream(job.filePath);
    stream.pipe(res);
    stream.on('close', () => job.cleanup());
    stream.on('error', () => job.cleanup());
  } catch (err) {
    console.error('[StreamVault Stream Error]:', err.message);
    if (!res.headersSent) {
      res.status(500).json({ ok: false, error: err.message });
    }
  }
});

ensureYtDlp().catch((err) => {
  console.warn('[StreamVault] Startup yt-dlp check warning:', err.message);
});

app.listen(PORT, '0.0.0.0', () => {
  console.log(`StreamVault v3.5 Multi-Engine Video Downloader listening on port ${PORT}`);
});
